-- purpose: 令和7年第4回(12月)定例会のデータを会議録から新規投入する
-- affected: assemblies, council_members, agenda_items, general_questions, question_topics
-- sources:
--   https://www.town.hirokawa.fukuoka.jp/material/files/group/37/071204.pdf (12/4 開会・一般質問)
--   https://www.town.hirokawa.fukuoka.jp/material/files/group/37/071211.pdf (12/11 議案審議)
-- notes: total_agenda_itemsは開会時の町長挨拶で示された「人事案件2件、町道の認定1件、
--        契約の締結1件、条例の制定3件、条例の一部改正2件、補正予算5件の計14件」に基づく。
--        議員発議の発議第1号(意見書、起立少数で否決)はこの14件には含まれないが、
--        20260815120000の発委第1号と同様の扱いでagenda_itemsに1件追加登録する(合計15件)。
--        agenda_items.statusは可決・否決・継続審査・撤回・未審議の5値のみ許可されるため、
--        同意第3号・同意第4号(同意)はいずれも可決に、実際の区分の違いはcategory・
--        proposal_reasonの文中に残す。
--        council_membersは氏名で既存レコードを検索し、水落龍彦のみ新規作成する
--        (会議録記載の応招議員一覧により10番と確認できるためseat_number=10を設定)。

do $$
declare
  v_assembly_id uuid := '7dd65f4c-fad4-45e3-aa93-cf48edc42e6a';
begin

  -- 冪等ガード: 既に投入済みなら何もしない
  if exists (
    select 1 from public.assemblies
    where fiscal_year = 2025
      and session_type = '定例会'
      and session_number = 4
  ) then
    raise notice '既に投入済みのためスキップします';
    return;
  end if;

  insert into public.assemblies
    (id, name, session_type, session_number, fiscal_year, start_date, end_date, total_agenda_items)
  values
    (v_assembly_id, '令和7年第4回定例会', '定例会', 4, 2025, '2025-12-04', '2025-12-11', 14);

  -- council_members: 水落龍彦のみ本番に未登録のため追加する
  insert into public.council_members (id, name, seat_number, role)
  select '8a805f79-1c3e-4715-a4de-16dcf276727d', '水落龍彦', 10, '一般'
  where not exists (select 1 from public.council_members where name = '水落龍彦');

  -- agenda_items
  insert into public.agenda_items
    (id, assembly_id, item_number, title, category, proposal_reason, status, decided_on, display_order)
  values
    ('7198bebe-9b9e-406a-9273-76a5f7fe6539', v_assembly_id, '同意第3号', '広川町公平委員会委員の選任に対する同意について', '人事', '広川町公平委員会委員として藤島弘義氏を選任したいので、地方公務員法第9条の2第2項の規定により議会の同意を求めるもの。委員麻生登喜子氏の任期が令和7年12月19日をもって満了することに伴う後任選任。', '可決', '2025-12-11', 1),
    ('df7a3351-2953-49a7-a6a2-0804d163a06c', v_assembly_id, '同意第4号', '広川町教育委員会委員の任命に対する同意について', '人事', '広川町教育委員会委員として貞苅えり子氏を任命したいので、地方教育行政の組織及び運営に関する法律第4条第2項の規定により議会の同意を求めるもの。貞苅えり子氏の任期満了(令和7年12月19日)に伴う再任。', '可決', '2025-12-11', 2),
    ('d1d4d904-fcc6-49a9-98fe-32e9ec5288f4', v_assembly_id, '議案第60号', '町道路線の認定について', '町道の認定', '町道路線として湯布線(路線番号608、起点:広川町大字広川字湯布190番1地先、終点:同192番地先)を新設整備し町道として管理するため、道路法第8条第1項の規定に基づき町議会の議決を求めるもの。', '可決', '2025-12-11', 3),
    ('a19e5213-2d1e-4299-b373-ec73b434c701', v_assembly_id, '議案第61号', '長延逆瀬谷線道路災害復旧工事に係る変更契約の締結について', '契約の締結', '長延逆瀬谷線道路災害復旧工事について、ポンプ施設の移設や上水道管の再利用不可、護床ブロックの追加等により工事費を増額する必要が生じたため、契約額を126,500千円から129,170,800円に変更する契約を締結するもの(契約の相手方:株式会社広建)。', '可決', '2025-12-11', 4),
    ('c3b1086f-1797-4315-b88e-b1aa96aa5c9f', v_assembly_id, '議案第62号', '広川町情報通信技術を活用した行政の推進に関する条例の制定について', '条例の制定', '行政手続等を電子的に実施できる枠組みを整備し、関係者の利便性向上と行政運営の効率化を図るため制定するもの。電子申請、電子的な処分通知、文書の電磁的記録による作成・保存等について規定する。', '可決', '2025-12-11', 5),
    ('e4b19ce7-746c-4abc-afce-a5fb8c43124e', v_assembly_id, '議案第63号', '広川町教育施設建設委員会設置条例の制定について', '条例の制定', '公立教育施設(上広川小学校の移転等)の建設を円滑に進めるため、建設計画の策定や進捗状況等について調査・審議する建設委員会を設置するため制定するもの。委員は15名以内で、地域代表・学校関係者・学識経験者・町議会議員等で構成する。', '可決', '2025-12-11', 6),
    ('3def65a4-9b72-4b49-a447-4c43de2059f1', v_assembly_id, '議案第64号', '広川町乳児等通園支援事業の設備及び運営に関する基準を定める条例の制定について', '条例の制定', '国が定める乳児等通園支援事業(こども誰でも通園制度)の設備及び運営に関する基準が制定されたことに伴い制定するもの。令和8年4月の制度本格実施に向け、町は既存保育所等の空き定員を活用する余裕活用型での実施を予定している。', '可決', '2025-12-11', 7),
    ('63ccc11b-409a-49af-9f8e-f738d0c0ae3d', v_assembly_id, '議案第65号', '広川町職員の給与に関する条例の一部改正について', '条例の改正', '令和7年人事院勧告に準じて、俸給月額並びに期末手当及び勤勉手当等諸手当の支給額を改定するため一部改正するもの。期末・勤勉手当は合わせて年0.05月分増額、通勤手当も増額改定する。', '可決', '2025-12-11', 8),
    ('ac78510a-948d-4d9b-8d65-24317291473e', v_assembly_id, '議案第66号', '広川町会計年度任用職員の給与及び費用弁償に関する条例の一部改正について', '条例の改正', '一般職の職員の給与改定に準じて、会計年度任用職員の給与を改定するため一部改正するもの。期末手当を年0.05月分増額する。', '可決', '2025-12-11', 9),
    ('81b3afd9-8495-4e19-91d7-8941fbb5d822', v_assembly_id, '議案第67号', '令和7年度広川町一般会計補正予算（第4号）について', '補正予算', '歳入歳出予算の総額に歳入歳出それぞれ16,093千円を追加し、予算総額を9,847,329千円とするもの。人事院勧告に伴う給与改定及び10月の人事異動による人件費の補正(全体で19,949千円増額)が主な内容で、全国瞬時警報システム更新工事費等も計上する。', '可決', '2025-12-11', 10),
    ('b35ccac6-3bf7-43d6-8d4a-412d14da8f39', v_assembly_id, '議案第68号', '令和7年度広川町国民健康保険特別会計補正予算（第3号）について', '補正予算', '既定の予算総額から23,128千円を減額し、予算総額を2,270,831千円とするもの。県負担金(普通交付金)の減額のほか、療養給付費負担金の減額、普通交付金精算返納金の増額が主な内容。', '可決', '2025-12-11', 11),
    ('13fa66b0-5b99-452b-b8e7-4766893accee', v_assembly_id, '議案第69号', '令和7年度広川防災ダム管理特別会計補正予算（第2号）について', '補正予算', '既定の予算総額に247千円を追加し、予算総額を33,172千円とするもの。職員人件費の補正が内容。', '可決', '2025-12-11', 12),
    ('205f6d88-f70a-4cea-88cf-b8f774cae28f', v_assembly_id, '議案第70号', '令和7年度広川町水道事業会計補正予算（第2号）について', '補正予算', '収益的支出を522千円増額、資本的収入を100千円減額・資本的支出を349千円増額し、予算総額408,578千円とするもの。給与改定等に伴う人件費の補正が主な内容。', '可決', '2025-12-11', 13),
    ('6740526d-2b2d-42f9-b249-acab3acd750d', v_assembly_id, '議案第71号', '令和7年度広川町下水道事業会計補正予算（第2号）について', '補正予算', '収益的収入を1,026千円・収益的支出を495千円減額、資本的収入を3,905千円・資本的支出を209千円増額し、予算総額612,994千円とするもの。人件費の補正及び受益者負担金の賦課実績に伴う増額が内容。', '可決', '2025-12-11', 14),
    ('90ba5155-e8f7-49ae-8a38-56eabc02c544', v_assembly_id, '発議第1号', '地域医療提供体制の維持・確保のための診療報酬改定等を求める意見書の提出について', '意見書', '物価高騰・人件費上昇に診療報酬改定が追いつかず医療機関の経営難が深刻化しているとして、国に対し臨時的な診療報酬改定や補助制度の創設・拡充を求めるもの(提出者:江藤美代子議員)。国民負担・町財政への影響や医療制度全体の改革の必要性等について質疑・討論が行われ、起立採決の結果、起立少数で否決された。', '否決', '2025-12-11', 15);

  -- general_questions: council_member_idは氏名で既存レコードを解決する
  insert into public.general_questions (id, assembly_id, council_member_id, order_number, title)
  select 'ab1103b7-58bb-4c81-9bb3-954b697e63b4', v_assembly_id, cm.id, 1, 'ボランティアの現状を踏まえた今後の本町の方向性について'
  from public.council_members cm where cm.name = '下田めぐみ';

  insert into public.general_questions (id, assembly_id, council_member_id, order_number, title)
  select 'b9466d3c-1850-4a33-b0c1-f3c78bbf6158', v_assembly_id, cm.id, 2, '大阪・関西万博への対応状況、機関誌・報道新聞等の購入状況について'
  from public.council_members cm where cm.name = '竹下英治';

  insert into public.general_questions (id, assembly_id, council_member_id, order_number, title)
  select 'a06f93b1-8685-4a6a-93a4-4e6af2a1b74a', v_assembly_id, cm.id, 3, '農地集約・新規就農者支援の状況、防犯カメラの設置について'
  from public.council_members cm where cm.name = '辻満晴';

  insert into public.general_questions (id, assembly_id, council_member_id, order_number, title)
  select '9a46e854-d016-4ea6-b6b4-0a15fb1b8764', v_assembly_id, cm.id, 4, '広川町中央公民館、こども誰でも通園制度、広川町の農業について'
  from public.council_members cm where cm.name = '江藤美代子';

  insert into public.general_questions (id, assembly_id, council_member_id, order_number, title)
  select 'd7c5682e-443c-48f8-85a6-e2e5bb30395a', v_assembly_id, cm.id, 5, '豊かなまちづくりのための施策、広報・啓発活動、人権啓発活動、教職員の不祥事防止について'
  from public.council_members cm where cm.name = '藤島玄稔';

  insert into public.general_questions (id, assembly_id, council_member_id, order_number, title)
  select 'df56059f-8f09-4e50-8f89-cb7dc28a6b74', v_assembly_id, cm.id, 6, '町の観光推進、鳥獣害対策について'
  from public.council_members cm where cm.name = '池尻浩一';

  insert into public.general_questions (id, assembly_id, council_member_id, order_number, title)
  select 'f2528402-e901-4899-8bf5-d73e46b49fab', v_assembly_id, cm.id, 7, '多文化共生の現状と今後の取組について'
  from public.council_members cm where cm.name = '水落龍彦';

  insert into public.general_questions (id, assembly_id, council_member_id, order_number, title)
  select 'ee5e322f-c2c1-4cb4-82ba-f52f96705789', v_assembly_id, cm.id, 8, '主任児童委員の定数欠について'
  from public.council_members cm where cm.name = '梶原一美';

  -- question_topics: 会議録の質疑応答の内容に基づく
  insert into public.question_topics
    (id, general_question_id, topic_title, raw_excerpt, department, display_order)
  values
    ('f4f97b64-6d1f-4c12-9f90-84ef706591b9', 'ab1103b7-58bb-4c81-9bb3-954b697e63b4', 'ボランティア人材の確保・育成と有償ボランティア制度の検討', 'ボランティア活動の現状と今後の確保・育成策について質問。町は、団体登録32・個人登録16のほか生活支援・災害ボランティア等が地域ニーズに応じて活動していると説明。下田議員は生活支援分野の担い手不足を指摘し、有償ボランティアへのポイント制度導入や地域振興券での還元を提案したが、企画課長は現時点で検討していないと答弁。学生ボランティア(ジュニアリーダー等72名)や公民館の担い手不足についても質疑があった。', NULL, 1),
    ('1ddcf98c-28b3-4d29-babf-475cc8a4c500', 'b9466d3c-1850-4a33-b0c1-f3c78bbf6158', '大阪・関西万博「地方創生SDGsフェス」への対応状況', '大阪・関西万博の地方創生SDGsフェスへの出展状況を質問。町長は、内閣府から出展依頼があったが財源・準備等を総合的に勘案し出展は見送ったと答弁。一方「TEAM EXPO 2025」には久留米絣協同組合青年部が広川町の伝統工芸をPRし、技術・伝統ミャクミャク賞を受賞したと紹介。竹下議員は八女市の出展実績(費用400万円、来場者延べ4万人超)を示し費用対効果を指摘し、町の判断の妥当性を問うた。', '企画課', 1),
    ('d7315c6d-2148-4a8d-a94d-702eb78fc8a8', 'b9466d3c-1850-4a33-b0c1-f3c78bbf6158', '機関誌・報道新聞等の購入状況の見直し', '役場・図書館・学校で購入する機関誌・報道新聞の購入状況を質問。議会事務局・町長部局で機関誌12誌・新聞5紙、年間571,271円を購入していると答弁。竹下議員は日本農業新聞(JA100%出資)など発行元の性質を踏まえた購入の見直しを提案し、総務課長は令和8年度予算編成の中で見直し結果を報告すると答弁した。', '総務課', 2),
    ('2cf077c9-174c-425f-9114-e9523701cadb', 'a06f93b1-8685-4a6a-93a4-4e6af2a1b74a', '農地集約の進捗状況と新規就農者支援', '担い手への農地集積率は令和6年度70.8%、令和7年10月現在71.2%(集積面積483ha)。今年3月策定の地域計画(8地区・総面積447ha)では担い手割合37%・集積率60.2%と全体より低い状況が判明。新規就農者数は令和2〜6年度で29名(親元就農16名)。辻議員は八女市の独自加算助成(年100万円上限)を紹介し町独自の上乗せ助成の検討を求めたが、産業課長は財源確保が課題であり調査研究するにとどめた。', '産業課', 1),
    ('c59f15ed-43f8-462a-a419-fc53616613db', 'a06f93b1-8685-4a6a-93a4-4e6af2a1b74a', '防犯カメラの設置に対する考え方', '町設置の防犯カメラは36台、年間維持費約977千円、新設1台あたり約500千円。県の防犯対策カメラ設置支援事業(2分の1補助)を活用し、毎年2台程度の増設を予定。個人・団体設置への補助制度は、プライバシー等の観点から八女警察署と協議中で未整備。農政連広川支部からの盗難対策要望に対しては県の間接補助制度の周知や生産部会補助金の活用を検討するとした。', '企画課', 2),
    ('3e4695c8-715c-4671-8188-ff9537f0435c', '9a46e854-d016-4ea6-b6b4-0a15fb1b8764', '広川町中央公民館の実態と条例の整合性', '広川町公民館条例上は中央公民館の設置・位置(現庁舎)が定められているが、実際の建物機能は平成26年の町民交流センター設置に伴い移管され、現在は生涯学習課内に中央公民館長(兼社会教育指導員)を置く形のみが残っている。江藤議員は条例と実態の「ねじれ」を指摘し条例改正での整合性確保を提案。総務課長は令和2年の条例改正で誤解を生じた可能性を認め、今後検討を重ねるとした。', '生涯学習課', 1),
    ('649bf0ef-2077-4299-97e2-6e9631e29812', '9a46e854-d016-4ea6-b6b4-0a15fb1b8764', 'こども誰でも通園制度の実施に向けた検討状況', '令和8年4月本格実施予定のこども誰でも通園制度について、保護者アンケート(123世帯対象、回答率40%)では利用希望が22.8%。広川町は既存保育所の空き定員を活用する「余裕活用型」で実施予定、利用料は1時間300円(国基準)。江藤議員は保育士不足や事故対応・在園児への影響等の懸念を指摘し、国への処遇改善要望を求めた。', '子ども課', 2),
    ('f5b82a16-caf3-402f-aae1-64db191e13ac', '9a46e854-d016-4ea6-b6b4-0a15fb1b8764', '広川町の農業の現状と課題', '広川町の農業経営体数・就業人口は減少傾向(2020年農林業センサスで経営体367、就業人口959、平均年齢62.1歳)。認定農業者163名中26名が70歳以上。第5次総合計画の新規就農目標25名(令和6〜9年度)に対し現在12名。中間管理機構への集積は目標118haに対し95ha(令和7年時点)。江藤議員は労働時間に見合わない収益性の低さを指摘し、町の長期ビジョンを問うた。', '産業課', 3),
    ('e2d77a9f-7bfe-44da-b750-602d2fd9078e', 'd7c5682e-443c-48f8-85a6-e2e5bb30395a', '豊かなまちづくりのための施策(組織改編・バイパス事業等)', '令和7年10月の組織変更で新設した都市計画課(国道3号バイパス事業等の一元化)と改編した産業課(農業土木係を建設課へ移管)の狙いを説明。国道3号広川八女バイパスは令和8年度から用地買収着手予定。自主財源は町税が一般会計収入の25.9%(令和6年度)、中核工業団地・新産業団地の本社立地割合は約28%と答弁。', '企画課', 1),
    ('5a9e497f-11e4-419f-a178-a0a622bc9385', 'd7c5682e-443c-48f8-85a6-e2e5bb30395a', '広報活動・啓発活動について', '広報ヒロカワの編集方針(視線動線を意識したレイアウト、表情の伝わる写真選定)を説明。テレビ・ラジオ番組案内のLINE掲載は著作権等の制約から町主催・協議済み番組に限定。ユーチューブでの発信は肖像権配慮等の労力から限定的に検討するとした。', '企画課', 2),
    ('0f5e0fcc-52fd-4027-97a3-02dcce7fbd5b', 'd7c5682e-443c-48f8-85a6-e2e5bb30395a', '人権啓発活動について', 'なるほど人権セミナー(7月・同和問題)とひろかわセミナー(11〜12月)の内容や講師選定方針を説明。昨年度参加者は計372人(地域住民約18%)、地域巡回講座は209人参加。他行政区の講座への参加も可能と回答。', '生涯学習課', 3),
    ('9a7b7a35-6413-447b-a127-28984a0ebd03', 'd7c5682e-443c-48f8-85a6-e2e5bb30395a', '教職員の不祥事防止に向けての取組', '広川町不祥事防止対策検討委員会を年6回開催し、各学校の取組状況共有や研修、全教職員へのメンタルヘルスチェックを実施。藤島議員は過去に不祥事説明の場への傍聴を断られた経緯を挙げ、住民への情報発信を求めた。', NULL, 4),
    ('7479f036-7453-4bd3-8acd-df14023f0e2e', 'df56059f-8f09-4e50-8f89-cb7dc28a6b74', '町の観光推進(イベント負担・イチョウまつり・オープンガーデン)', '広川まつり担当職員2名の時間外勤務は今年度120時間、代休・超過勤務手当は完全消化・支給と説明。イチョウまつりは今年度過去最多規模の来場でオーバーツーリズム状態となり、臨時駐車場を超える渋滞が発生。イチョウ畑は所有者の高齢化・後継者不在が将来課題とされ、町・観光協会との協議を検討。オープンガーデンの拡大は現時点で検討していないと答弁。', '産業課', 1),
    ('4f1f82bb-0b5c-4cb8-b9e2-2efc2c2e42c4', 'df56059f-8f09-4e50-8f89-cb7dc28a6b74', '鳥獣害対策について', '令和6年度の捕獲数は413匹(過去最多)、被害農地62アール、被害額4,141千円。令和7年度は10月末時点206匹。八女猟友会広川支部20名のうち活動12名。報奨金は近隣で1頭8千円程度、ガバメントハンター導入は当面見送り、後継者育成として若手農家への免許取得呼びかけ(直近数年で4名)を実施していると答弁。', '産業課', 2),
    ('a045527f-3eaf-4501-9108-efade0a8743e', 'f2528402-e901-4899-8bf5-d73e46b49fab', '多文化共生の現状と今後の取組', '在住外国人は11月現在543人、10年間で3.4倍増。国籍はベトナム約40%・インドネシア約20%、在留資格は技能実習・特定技能が約76%。2022年策定の多文化共生推進計画は2026年からの新計画をプロジェクトチームで検討中。日本語教室は参加者減少により再開未定、多文化共生事業の予算は年間約300千円。', '生涯学習課', 1),
    ('ad14819f-6b89-4e35-bf91-e85700901ee6', 'ee5e322f-c2c1-4cb4-82ba-f52f96705789', '主任児童委員の定数欠について', '主任児童委員の定数3名に対し、令和4年12月以降1名(現在は0名)で運用。定数欠の要因として、専門性・倫理観を要する任務ゆえの候補者不足と職務負担の大きさを説明。福祉課長は各校区に1名必要であり1名では不足していると認め、厚生労働省の民生委員制度に関する調査研究事業の動向も踏まえ、専門性を持つ人材の選任を目指すと答弁した。', '福祉課', 1);

end $$;
